document.addEventListener("copy",function(e){var s=window.getSelection();if(s.isCollapsed||!s.rangeCount)return;var f=s.getRangeAt(0).cloneContents();if(!f.querySelector(".katex-mathml"))return;f.querySelectorAll(".katex-mathml").forEach(function(m){var a=m.querySelector("annotation");if(a){m.replaceWith(document.createTextNode(a.textContent))}});f.querySelectorAll(".katex-html").forEach(function(h){h.remove()});var d=document.createElement("div");d.appendChild(f);e.clipboardData.setData("text/plain",d.textContent);e.clipboardData.setData("text/html",d.innerHTML);e.preventDefault()});